use mic_protocol::lab::TransportConfig;
use serde::{Deserialize, Serialize};
use serde_json::{Value,json};
use std::collections::{BTreeMap,BTreeSet};
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Combination {pub combination_id:String,pub name:String,pub config:TransportConfig,pub enabled:bool,pub duration_seconds:Option<u64>,pub unsupported_reason:Option<String>}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Plan {pub plan_id:String,pub name:String,pub created_at:u64,pub device_id:String,pub matrix_parameters:Matrix,pub selected_combinations:Vec<Combination>,pub global_settings:Settings,pub execution_order:Vec<(String,u32)>,pub random_seed:u64}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Matrix {pub frame:Vec<u16>,pub fec:Vec<bool>,pub jitter:Vec<u16>}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Settings {pub duration_seconds:u64,pub warmup_seconds:u64,pub repetitions:u32,pub mode:String,pub order:String}
impl Matrix {pub fn build(&self)->Vec<Combination>{let mut seen=BTreeSet::new();let mut out=vec![];for &f in &self.frame{for &e in &self.fec{for &j in &self.jitter{if !seen.insert((f,e,j)){continue}let mut c=TransportConfig::default();c.frame_duration_ms=f;c.fec.enabled=e;c.jitter_buffer_target_ms=j;let reason=c.validate().err().map(|e|e.to_string()).or_else(||(![20,30,50,80,100].contains(&j)).then(||"unsupported sweep jitter target".into()));out.push(Combination{combination_id:format!("{f}-{e}-{j}"),name:format!("{f} ms / FEC {e} / {j} ms"),config:c,enabled:reason.is_none(),duration_seconds:None,unsupported_reason:reason});}}}out}}
impl Plan {pub fn validate(&mut self)->Result<(),String>{let s=&self.global_settings;if !(10..=180).contains(&s.duration_seconds)||s.warmup_seconds>60||!(1..=5).contains(&s.repetitions)||!["Automatic","Step-by-step"].contains(&s.mode.as_str())||!["Fixed","Randomized"].contains(&s.order.as_str()){return Err("invalid global settings".into())}if self.selected_combinations.len()>20{return Err("at most 20 combinations".into())}let candidates=self.matrix_parameters.build();let mut seen=BTreeSet::new();self.execution_order.clear();for c in &mut self.selected_combinations{let base=candidates.iter().find(|x|x.config==c.config&&x.combination_id==c.combination_id).ok_or("combination is outside matrix")?;c.unsupported_reason=base.unsupported_reason.clone();if !seen.insert(c.combination_id.clone()){return Err("duplicate combination".into())}if let Some(t)=c.duration_seconds{if !(10..=180).contains(&t){return Err("invalid duration override".into())}}if c.enabled{if c.unsupported_reason.is_some(){return Err("unsupported enabled combination".into())}for r in 1..=s.repetitions{self.execution_order.push((c.combination_id.clone(),r));}}}if self.execution_order.is_empty(){return Err("no enabled combinations".into())}if s.order=="Randomized"{use rand::{SeedableRng,seq::SliceRandom};self.execution_order.shuffle(&mut rand::rngs::StdRng::seed_from_u64(self.random_seed));}Ok(())}}
pub type Counters=BTreeMap<String,u64>;
pub fn counters(s:&Value,d:&Value)->Counters{let mut out=Counters::new();for k in ["authenticated_audio_packets","received_datagrams","received_datagram_bytes","authenticated_pcm_bytes","lost_packets","sequence_gaps","late_packet_drops","jitter_buffer_drops","authentication_failures","buffer_underruns","callback_starvations","delivered_samples","jitter_missing_samples_fed","input_samples_consumed","output_frames_requested"]{if let Some(v)=s["metrics"][k].as_u64(){out.insert(k.into(),v);}}for k in ["pipeline_inserted_us","prefill_us","starvation_us"]{if let Some(v)=s["metrics"]["output_diagnostics"][k].as_u64(){out.insert(k.into(),v);}}if let Some(f)=s["fec"].as_object(){for(k,v)in f{if let Some(n)=v.as_u64(){out.insert(format!("fec_{k}"),n);}}}if let Some(types)=d["event_types"].as_array(){for(i,k)in types.iter().enumerate(){if let(Some(k),Some(v))=(k.as_str(),d["counts"][i].as_u64()){out.insert(k.into(),v);}}}out}
pub fn delta(a:&Counters,b:&Counters)->Result<Counters,String>{a.iter().map(|(k,v)|b.get(k).and_then(|n|n.checked_sub(*v)).map(|n|(k.clone(),n)).ok_or_else(||format!("counter unavailable/reset: {k}"))).collect()}
pub fn derived(d:&Counters,t:f64)->Value{let rate=|k:&str|d.get(k).map(|v|*v as f64/t);json!({"authenticated_audio_pps":rate("authenticated_audio_packets"),"underruns_per_second":rate("buffer_underruns"),"late_drops_per_second":rate("late_packet_drops"),"resyncs_per_second":rate("BUFFER_RESYNC"),"callback_starvations_per_second":rate("callback_starvations"),"fec_recovered":d.get("fec_recovered"),"missing_audio_samples_ratio":d.get("jitter_missing_samples_fed").zip(d.get("delivered_samples")).and_then(|(m,n)|(*n>0).then(||*m as f64/ *n as f64)),"end_to_end_latency_ms":null})}
pub fn comparison(runs:&[Value])->Value{let mut groups:BTreeMap<String,Vec<&Value>>=BTreeMap::new();for r in runs{groups.entry(r["combination_id"].as_str().unwrap_or("").into()).or_default().push(r);}json!(groups.into_iter().map(|(id,rs)|{let valid:Vec<_>=rs.iter().filter(|r|r["validity"]=="VALID").collect();let mut stats=serde_json::Map::new();for k in ["authenticated_audio_pps","underruns_per_second","late_drops_per_second","resyncs_per_second","callback_starvations_per_second","fec_recovered","missing_audio_samples_ratio"]{let mut v:Vec<f64>=valid.iter().filter_map(|r|r["derived_metrics"][k].as_f64()).collect();v.sort_by(f64::total_cmp);if !v.is_empty(){let n=v.len();let mean=v.iter().sum::<f64>()/n as f64;stats.insert(k.into(),json!({"mean":mean,"median":(v[(n-1)/2]+v[n/2])/2.,"min":v[0],"max":v[n-1],"standard_deviation":(v.iter().map(|x|(x-mean).powi(2)).sum::<f64>()/n as f64).sqrt()}));}}json!({"combination_id":id,"config":rs[0]["requested_config"],"repetitions":rs.len(),"valid_runs":valid.len(),"metrics":stats})}).collect::<Vec<_>>())}
pub fn csv(summary:&Value)->String{let keys=["underruns_per_second","late_drops_per_second","resyncs_per_second","authenticated_audio_pps","fec_recovered","missing_audio_samples_ratio"];let mut out=String::from("frame_ms,fec,jitter_ms,repetitions,valid_runs");for k in keys{for stat in ["mean","median","min","max","standard_deviation"]{out.push_str(&format!(",{k}_{stat}"));}}out.push('\n');for r in summary.as_array().unwrap_or(&vec![]){out.push_str(&format!("{},{},{},{},{}",r["config"]["frame_duration_ms"],r["config"]["fec"]["enabled"],r["config"]["jitter_buffer_target_ms"],r["repetitions"],r["valid_runs"]));for k in keys{for stat in ["mean","median","min","max","standard_deviation"]{out.push(',');if let Some(n)=r["metrics"][k][stat].as_f64(){out.push_str(&n.to_string());}}}out.push('\n');}out}
